import { strict as assert } from "node:assert";
import { test } from "node:test";
import { attemptsAllowed } from "./client/fetcher.mjs";
import { backoffSchedule } from "./client/queue.mjs";

test("allows five attempts", () => {
  assert.equal(attemptsAllowed(), 5);
});

test("schedules a backoff per attempt", () => {
  assert.deepEqual(backoffSchedule(), [1, 2, 4, 8, 16]);
});

